 private DirectorStore store;private String projectId;private JSONObject project;private LinearLayout body;private TextView status;private EditText title;private EditText quickText;private boolean advanced=false;private AlertDialog generationConfirmation;private volatile String lastOperationError=null;private boolean busy=false;private final Handler handler=new Handler();
 private final Runnable poll=new Runnable(){public void run(){try{if(!busy&&projectId!=null){File f=new File(store.folder(projectId),"job.json");if(f.isFile()){JSONObject state=DirectorStore.read(f);if(!state.optBoolean("terminal")&&state.optString("stage").equals("RUNNING"))refresh();}}}catch(Exception e){status.setText(e.getMessage());}handler.postDelayed(this,20000);}};
 private void task(Work work,Runnable done){lastOperationError=null;busy=true;if(quickText!=null){quickText.setEnabled(false);title.setEnabled(false);}status.setText("Trabajando… Mantén abierta la aplicación durante la subida o descarga.");AutoStudioApp.IO.execute(()->{try{work.run();runOnUiThread(()->{busy=false;if(quickText!=null){quickText.setEnabled(true);title.setEnabled(true);}done.run();});}catch(Exception e){runOnUiThread(()->{busy=false;if(quickText!=null){quickText.setEnabled(true);title.setEnabled(true);}lastOperationError=e.getMessage();status.setText(e.getMessage());Ui.error(this,e.getMessage());});}});}
