  Ui.para(body,"1 · Título");title=new EditText(this);title.setId(2401);title.setSingleLine(true);title.setHint("Por ejemplo: Las luces de Hessdalen");title.setText(project.optString("title"));body.addView(title);
  Ui.para(body,"2 · Texto que se narrará");quickText=new EditText(this);quickText.setId(2402);quickText.setGravity(android.view.Gravity.TOP);quickText.setMinLines(5);quickText.setMaxLines(9);quickText.setHint("Pega aquí todo el texto. Nosotros lo repartimos entre las imágenes.");quickText.setText(quick.optString("text"));quickText.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);body.addView(quickText);
